<?php
 namespace Dicom; define('TOOLKIT_DIR', realpath(__DIR__ . '/../../../../bin/dcmtk/bin') . '/'); if (!defined('OS_WINDOWS')) { if (PATH_SEPARATOR === ';' || PHP_SHLIB_SUFFIX === 'dll' || strtolower(substr(PHP_OS, 0, 3)) === 'win') { define('OS_WINDOWS', true); } else { define('OS_WINDOWS', false); } } if (OS_WINDOWS) { define('BIN_ECHOSCU', TOOLKIT_DIR . 'echoscu.exe'); define('BIN_FINDSCU', TOOLKIT_DIR . 'findscu.exe'); define('BIN_GETSCU', TOOLKIT_DIR . 'getscu.exe'); define('BIN_MOVESCU', TOOLKIT_DIR . 'movescu.exe'); define('BIN_DUMP2DCM', TOOLKIT_DIR . 'dump2dcm.exe'); define('BIN_DCMDUMP', TOOLKIT_DIR . 'dcmdump.exe'); define('BIN_STORESCU', TOOLKIT_DIR . 'storescu.exe'); } else { define('BIN_ECHOSCU', 'echoscu'); define('BIN_FINDSCU', 'findscu'); define('BIN_GETSCU', 'getscu'); define('BIN_MOVESCU', 'movescu'); define('BIN_DUMP2DCM', 'dump2dcm'); define('BIN_DCMDUMP', 'dcmdump'); define('BIN_STORESCU', 'storescu'); } function executeCmd ($command, &$exitcode = null) { $command .= ' 2>&1'; if (($handle = popen($command, 'r')) === false) { throw new \Exception("Ошибка запуска команды \"$command\""); } $log = ''; while (!feof($handle)) { $log .= fread($handle, 4096); } $exitcode = pclose($handle); if (mb_detect_encoding($log, 'UTF-8', true) === false) { $log = mb_convert_encoding($log, 'UTF-8', 'CP1251'); } return $log; } 